head.script:
(function () {
  const XHTML_NS = 'http://www.w3.org/1999/xhtml';
  const root = document.querySelector('foreignObject').firstElementChild;
  const createElementNS = document.createElementNS.bind(document);
  Object.defineProperty(document, 'head', { get: () => root.querySelector('head'), configurable: true });
  Object.defineProperty(document, 'body', { get: () => root.querySelector('body'), configurable: true });
  Object.defineProperty(document, 'documentElement', { get: () => root, configurable: true });
  document.createElement = function (tagName, options) {
    return createElementNS(XHTML_NS, tagName, options);
  };
})();

body.script:
(function () {
  var GAP = 15 * 60 * 1000, RETRY = 2 * 60 * 1000;
  try { localStorage.getItem('achroma-ad-interstitial-at'); } catch (e) { return; }
  function count(k) {
    try { fetch('/api/rt/e', { method: 'POST', body: k, keepalive: true, credentials: 'omit', headers: { 'Content-Type': 'text/plain' } }).catch(function () {}); } catch (e) { /* ads only */ }
  }
  function due(key) {
    var last = 0;
    try { last = Number(localStorage.getItem(key)) || 0; } catch (e) { return false; }
    return Date.now() - last >= GAP;
  }
  // Top-level elements of <body> and <html>: where Adcash puts its ad containers.
  function bodyKids() {
    var a = document.body ? Array.prototype.slice.call(document.body.children) : [];
    return a.concat(Array.prototype.slice.call(document.documentElement.children));
  }
  function added(before) {
    return bodyKids().filter(function (n) { return before.indexOf(n) === -1 && !/^(SCRIPT|STYLE|LINK|NOSCRIPT)$/.test(n.tagName); });
  }
  // One format: ask Adcash when due; whether anything appeared decides the next try.
  function slot(name, key, fn, onTop) {
    return function () {
      if (!due(key) || document.visibilityState === 'hidden' || !window.aclib || !window.aclib[fn]) return;
      try { localStorage.setItem(key, String(Date.now())); } catch (e) { return; }
      var before = bodyKids(), seen = false;
      // Anything the ad adds counts the moment it appears, so an ad closed within seconds
      // still counts as shown (and its 15 minutes stand) instead of looking like no ad.
      var mo = new MutationObserver(function () { if (!seen && added(before).length) seen = true; });
      try {
        mo.observe(document.documentElement, { childList: true });
        if (document.body) mo.observe(document.body, { childList: true });
      } catch (e) { /* ads only */ }
      count(name + ':ask');
      try { window.aclib[fn](name === 'inter' ? { zoneId: '12468914' } : { zoneId: '12469942' }); } catch (e) { count(name + ':error'); }
      var raise = function () {
        added(before).forEach(function (n) {
          try { if (getComputedStyle(n).position === 'fixed') n.style.setProperty('z-index', '2147483647', 'important'); } catch (e) { /* ads only */ }
        });
      };
      if (onTop) [500, 1500, 4000, 10000, 30000].forEach(function (ms) { setTimeout(raise, ms); });
      setTimeout(function () {
        var miss = key + '-miss', n = 0;
        mo.disconnect();
        if (seen || added(before).length) { count(name + ':shown'); try { localStorage.removeItem(miss); } catch (e) { /* ads only */ } return; }
        count(name + ':empty');
        // Retry sooner only 3 times in a row, so a missed detection can never mean ads every 2 minutes.
        try { n = (Number(localStorage.getItem(miss)) || 0) + 1; localStorage.setItem(miss, String(n >= 3 ? 0 : n)); } catch (e) { return; }
        if (n < 3) try { localStorage.setItem(key, String(Date.now() - GAP + RETRY)); } catch (e) { /* ads only */ }
      }, 8000);
    };
  }
  var slider = slot('slider', 'achroma-ad-slider-at', 'runVideoSlider', true);
  function start(src) {
    count('lib:' + src);
    // Interstitial (zone 12468914) removed 2026-11-19: its script opened advertiser tabs on
    // clicks even when no interstitial was visible. Only the slider runs.
    setTimeout(function () { slider(); setInterval(slider, 60 * 1000); }, 30 * 1000);
  }
  count('page');
  if (window.aclib && window.aclib.runVideoSlider) { start('root'); return; }
  function inject(src, done, fail) {
    var s = document.createElement('script');
    s.async = true;
    s.src = src;
    s.onload = function () { if (window.aclib && window.aclib.runVideoSlider) done(); else fail(); };
    s.onerror = fail;
    document.head.appendChild(s);
  }
  function own() {
    fetch('/api/rt/c7q2.js', { credentials: 'omit' })
      .then(function (r) { return r.ok ? r.text() : Promise.reject(); })
      .then(function (code) {
        inject(URL.createObjectURL(new Blob([code], { type: 'text/javascript' })), function () { start('own'); }, function () { count('lib:none'); });
      }, function () { count('lib:none'); });
  }
  // acscdn.com first (portable shells have no root page that loaded it), our copy if blocked.
  inject('https://acscdn.com/script/aclib.js', function () { start('acscdn'); }, own);
})();
